import re
from roman import to_roman

cases = {1:'I',4:'IV',5:'V',9:'IX',14:'XIV',40:'XL',44:'XLIV',49:'XLIX',
         90:'XC',99:'XCIX',400:'CD',444:'CDXLIV',500:'D',900:'CM',
         944:'CMXLIV',1994:'MCMXCIV',2024:'MMXXIV',3888:'MMMDCCCLXXXVIII',3999:'MMMCMXCIX'}
for n, exp in cases.items():
    got = to_roman(n)
    assert got == exp, f'{n}: got {got}, expected {exp}'
print('key cases: OK')

pat = re.compile(r'^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$')
def to_int(r):
    m = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    t = 0
    for i, c in enumerate(r):
        if i+1 < len(r) and m[c] < m[r[i+1]]:
            t -= m[c]
        else:
            t += m[c]
    return t

bad = [(n, to_roman(n)) for n in range(1, 4000)
       if not pat.match(to_roman(n)) or to_int(to_roman(n)) != n]
print('non-standard count:', len(bad), bad[:5])

for n in (0, 4000, -1):
    try:
        to_roman(n)
        print('FAIL: no exception for', n)
    except ValueError as e:
        print('ValueError preserved:', e)
print('ALL CHECKS DONE')
